@EnabledIfEnvironmentVariable(named="HELPDESK_DISPOSABLE_TEST_PG_URL",matches=".+")
class AssetAttachmentPostgresIntegrationTest {
 @DynamicPropertySource static void database(DynamicPropertyRegistry r)throws Exception{
  String url=newDatabase("asset_security_");r.add("spring.datasource.url",()->url);r.add("spring.datasource.username",()->System.getenv("HELPDESK_DISPOSABLE_TEST_PG_USER"));r.add("spring.datasource.password",()->System.getenv("HELPDESK_DISPOSABLE_TEST_PG_PASSWORD"));r.add("spring.datasource.driver-class-name",()->"org.postgresql.Driver");r.add("spring.jpa.database-platform",()->"org.hibernate.dialect.PostgreSQLDialect");r.add("spring.jpa.hibernate.ddl-auto",()->"validate");r.add("spring.flyway.enabled",()->true);
 }
 static Connection connect(String url)throws Exception{return DriverManager.getConnection(url,System.getenv("HELPDESK_DISPOSABLE_TEST_PG_USER"),System.getenv("HELPDESK_DISPOSABLE_TEST_PG_PASSWORD"));}
 static String newDatabase(String prefix)throws Exception{String base=System.getenv("HELPDESK_DISPOSABLE_TEST_PG_URL"),db=prefix+UUID.randomUUID().toString().replace("-","");try(var c=connect(base);var s=c.createStatement()){s.execute("CREATE DATABASE "+db);}return base.substring(0,base.lastIndexOf('/')+1)+db;}
 @Autowired WebApplicationContext context;@Autowired AssetRepository assets;@Autowired TicketRepository tickets;@Autowired UserRepository users;@Autowired TicketCommentRepository comments;@Autowired TokenService tokens;@Autowired PasswordEncoder encoder;@Autowired JdbcTemplate jdbc;
 ObjectMapper json=new ObjectMapper().findAndRegisterModules();MockMvc mvc;User admin,admin2,tech,requester,other;static String hash;
 @BeforeEach void setup(){mvc=MockMvcBuilders.webAppContextSetup(context).apply(SecurityMockMvcConfigurers.springSecurity()).build();if(hash==null)hash=encoder.encode(UUID.randomUUID().toString());admin=user(UserRole.ADMIN);admin2=user(UserRole.ADMIN);tech=user(UserRole.TECHNICIAN);requester=user(UserRole.REQUESTER);other=user(UserRole.REQUESTER);}
 User user(UserRole role){return users.saveAndFlush(new User("Homologação patrimonial",UUID.randomUUID()+"@asset.test",hash,role));}
 String code(){return "NB-"+UUID.randomUUID().toString().substring(0,12).toUpperCase(Locale.ROOT);}
 Map<String,Object> payload(String code,String status,Long version){var b=new HashMap<String,Object>();b.put("code",code);b.put("type","Notebook");b.put("description","Descrição patrimonial");b.put("status",status);if(version!=null)b.put("expectedVersion",version);return b;}
 record Result(int status,JsonNode body){}
 Result call(String method,String path,Object body,User actor)throws Exception{var req=switch(method){case "POST"->post(path);case "PUT"->put(path);case "PATCH"->patch(path);case "DELETE"->delete(path);default->get(path);};req.header("Authorization","Bearer "+tokens.generateToken(actor));if(body!=null)req.contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(body));var r=mvc.perform(req).andReturn().getResponse();return new Result(r.getStatus(),r.getContentAsString().isEmpty()?json.createObjectNode():json.readTree(r.getContentAsString()));}
 Asset asset()throws Exception{var r=call("POST","/assets",payload(code(),"IN_USE",null),admin);assertEquals(201,r.status);return assets.findById(r.body.path("id").asLong()).orElseThrow();}
 Ticket ticket(User owner,Asset asset){var t=new Ticket("Homologação "+UUID.randomUUID(),"Descrição do chamado",asset==null?TicketCategory.DUVIDA:TicketCategory.INCIDENTE_EQUIPAMENTO,TicketPriority.MEDIA,owner,asset);return tickets.saveAndFlush(t);}
 int audits(long id){return jdbc.queryForObject("SELECT count(*) FROM asset_audit_logs WHERE asset_id=?",Integer.class,id);}
 Result update(Asset a,String status,User actor)throws Exception{return call("PUT","/assets/"+a.getId(),payload(a.getCode(),status,a.getVersion()),actor);}
 List<Result> race(Callable<Result> one,Callable<Result> two)throws Exception{var barrier=new CyclicBarrier(2);try(var pool=Executors.newFixedThreadPool(2)){var a=pool.submit(()->{barrier.await(10,TimeUnit.SECONDS);return one.call();});var b=pool.submit(()->{barrier.await(10,TimeUnit.SECONDS);return two.call();});return List.of(a.get(30,TimeUnit.SECONDS),b.get(30,TimeUnit.SECONDS));}}
 @Test void creationNormalizesCodeAndRecordsActorAndAllNonSensitiveFields()throws Exception{String code=code();Instant before=Instant.now().minusSeconds(1);var r=call("POST","/assets",payload("  "+code.toLowerCase(Locale.ROOT)+"  ","IN_USE",null),admin);assertEquals(201,r.status);assertEquals(code,r.body.path("code").asText());assertEquals(0,r.body.path("version").asLong());var log=call("GET","/assets/"+r.body.path("id").asLong()+"/audit",null,admin);assertEquals(200,log.status);assertEquals(1,log.body.size());var event=log.body.get(0);assertEquals(admin.getId().longValue(),event.path("actorId").asLong());assertEquals("ASSET_CREATED",event.path("operation").asText());assertTrue(Instant.parse(event.path("occurredAt").asText()).isAfter(before));assertTrue(event.path("changes").has("code"));assertFalse(event.has("password"));assertFalse(event.has("token"));}
 @Test void spacesAndCaseDoNotCreateDuplicateCodes()throws Exception{var a=asset();for(String variant:List.of(a.getCode(),a.getCode().toLowerCase(Locale.ROOT),"  "+a.getCode()+"  "))assertEquals(409,call("POST","/assets",payload(variant,"IN_USE",null),admin).status);assertEquals(1,audits(a.getId()));}
 @Test void databaseIndexEnforcesNormalizedUniqueness()throws Exception{var a=asset();assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->jdbc.update("INSERT INTO assets(code,type,status) VALUES(?, 'Notebook','IN_USE')"," "+a.getCode().toLowerCase(Locale.ROOT)+" "));}
 @Test void twoAdministratorsCreatingSameCodeProduceOneCreationAndOneAudit()throws Exception{String code=code();var r=race(()->call("POST","/assets",payload(code,"IN_USE",null),admin),()->call("POST","/assets",payload(code.toLowerCase(Locale.ROOT),"IN_USE",null),admin2));assertEquals(List.of(201,409),r.stream().map(Result::status).sorted().toList());var a=assets.findByCode(code).orElseThrow();assertEquals(1,audits(a.getId()));}
 @Test void concurrentEditsDoNotOverwriteAndAuditExactlyOneWinner()throws Exception{var a=asset();var r=race(()->update(a,"INACTIVE",admin),()->update(a,"UNDER_MAINTENANCE",admin2));assertEquals(List.of(200,409),r.stream().map(Result::status).sorted().toList());var stored=assets.findById(a.getId()).orElseThrow();assertEquals(1,stored.getVersion());assertEquals(2,audits(a.getId()));var log=call("GET","/assets/"+a.getId()+"/audit",null,admin).body.get(1);assertEquals(stored.getStatus().name(),log.path("changes").path("status").path("newValue").asText());}
 @Test void effectiveNoopDoesNotChangeVersionOrAudit()throws Exception{var a=asset();assertEquals(200,update(a,"IN_USE",admin).status);assertEquals(1,audits(a.getId()));assertEquals(0,assets.findById(a.getId()).orElseThrow().getVersion());}
 @Test void absentAndStaleVersionsAreRejected()throws Exception{var a=asset();assertEquals(400,call("PUT","/assets/"+a.getId(),payload(a.getCode(),"INACTIVE",null),admin).status);assertEquals(400,call("PATCH","/assets/"+a.getId()+"/status",Map.of("status","INACTIVE"),admin).status);assertEquals(200,update(a,"INACTIVE",admin).status);assertEquals(409,update(a,"DISCARDED",admin).status);assertEquals(2,audits(a.getId()));}
 @ParameterizedTest @EnumSource(AssetStatus.class) void statusesAndAvailabilityRemainConsistent(AssetStatus status)throws Exception{var a=asset();assertEquals(200,call("PATCH","/assets/"+a.getId()+"/status",Map.of("status",status.name(),"expectedVersion",0),admin).status);boolean present=false;for(var item:call("GET","/assets/available",null,requester).body)if(item.path("id").asLong()==a.getId()){present=true;assertTrue(item.path("description").isNull());}assertEquals(status==AssetStatus.IN_USE,present);assertTrue(assets.existsById(a.getId()));}
 @Test void linkedIncidentsSurviveInformationMaintenanceAndDisposalChanges()throws Exception{var a=asset();var t=ticket(requester,a);t.setAttachmentData(TestImages.png());t.setAttachmentName("evidencia.png");t.setAttachmentContentType("image/png");t=tickets.saveAndFlush(t);comments.saveAndFlush(new TicketComment("Histórico preservado",t,requester));String original=jdbc.queryForObject("SELECT to_jsonb(t)::text FROM tickets t WHERE id=?",String.class,t.getId());
  var body=payload(a.getCode()+"-NOVO","UNDER_MAINTENANCE",0L);body.put("description","Informação revisada");assertEquals(200,call("PUT","/assets/"+a.getId(),body,admin).status);var stored=assets.findById(a.getId()).orElseThrow();assertEquals(200,update(stored,"DISCARDED",admin).status);assertEquals(original,jdbc.queryForObject("SELECT to_jsonb(t)::text FROM tickets t WHERE id=?",String.class,t.getId()));assertEquals(1,comments.findByTicketIdOrderByCreatedAtAsc(t.getId()).size());assertEquals(a.getId(),tickets.findById(t.getId()).orElseThrow().getAsset().getId());assertEquals(200,call("GET","/tickets/"+t.getId(),null,requester).status);assertEquals(400,call("POST","/tickets",Map.of("title","Novo incidente","description","Equipamento indisponível","category","INCIDENTE_EQUIPAMENTO","assetId",a.getId()),other).status);
 }
 @ParameterizedTest @EnumSource(UserRole.class) void directHttpPermissionsAreEnforced(UserRole role)throws Exception{var a=asset();User actor=switch(role){case ADMIN->admin;case TECHNICIAN->tech;case REQUESTER->requester;};assertEquals(role==UserRole.REQUESTER?403:200,call("GET","/assets/"+a.getId(),null,actor).status);assertEquals(role==UserRole.REQUESTER?403:200,call("GET","/assets",null,actor).status);assertEquals(role==UserRole.ADMIN?200:403,call("GET","/assets/"+a.getId()+"/audit",null,actor).status);if(role!=UserRole.ADMIN){assertEquals(403,call("POST","/assets",payload(code(),"IN_USE",null),actor).status);assertEquals(403,update(a,"DISCARDED",actor).status);assertEquals(403,call("PATCH","/assets/"+a.getId()+"/status",Map.of("status","INACTIVE","expectedVersion",0),actor).status);assertEquals(403,call("DELETE","/assets/"+a.getId(),null,actor).status);}}
 @Test void physicalDeletionIsRefusedWithoutLosingEquipment()throws Exception{var a=asset();assertEquals(400,call("DELETE","/assets/"+a.getId(),null,admin).status);assertTrue(assets.existsById(a.getId()));assertEquals(1,audits(a.getId()));}
 @Test void auditFailureRollsBackAssetFieldsVersionAndEvent()throws Exception{var a=asset();jdbc.execute("CREATE FUNCTION asset_audit_failure() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'isolated audit outage'; END $$");jdbc.execute("CREATE TRIGGER asset_audit_failure BEFORE INSERT ON asset_audit_changes FOR EACH ROW EXECUTE FUNCTION asset_audit_failure()");try{assertEquals(500,update(a,"DISCARDED",admin).status);}finally{jdbc.execute("DROP TRIGGER asset_audit_failure ON asset_audit_changes");jdbc.execute("DROP FUNCTION asset_audit_failure()");}var stored=assets.findById(a.getId()).orElseThrow();assertEquals(AssetStatus.IN_USE,stored.getStatus());assertEquals(0,stored.getVersion());assertEquals(1,audits(a.getId()));}
 @Test void creationAuditFailureAlsoRollsBackNewAsset()throws Exception{String code=code();jdbc.execute("CREATE FUNCTION asset_create_failure() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'isolated audit outage'; END $$");jdbc.execute("CREATE TRIGGER asset_create_failure BEFORE INSERT ON asset_audit_logs FOR EACH ROW EXECUTE FUNCTION asset_create_failure()");try{assertEquals(500,call("POST","/assets",payload(code,"IN_USE",null),admin).status);}finally{jdbc.execute("DROP TRIGGER asset_create_failure ON asset_audit_logs");jdbc.execute("DROP FUNCTION asset_create_failure()");}assertTrue(assets.findByCode(code).isEmpty());}
 @Test void eligibilityIsRecheckedAfterConcurrentStatusChange()throws Exception{var a=asset();try(var c=jdbc.getDataSource().getConnection()){c.setAutoCommit(false);try(var st=c.createStatement()){st.executeUpdate("UPDATE assets SET status='UNDER_MAINTENANCE',version=version+1 WHERE id="+a.getId());}try(var pool=Executors.newSingleThreadExecutor()){var future=pool.submit(()->call("POST","/tickets",Map.of("title","Concorrência elegibilidade","description","Somente teste isolado","category","INCIDENTE_EQUIPAMENTO","assetId",a.getId()),requester));boolean waiting=false;for(int i=0;i<100;i++){if(jdbc.queryForObject("SELECT count(*) FROM pg_stat_activity WHERE datname=current_database() AND wait_event_type='Lock'",Integer.class)>0){waiting=true;break;}Thread.sleep(20);}c.commit();assertEquals(409,future.get(20,TimeUnit.SECONDS).status);assertTrue(waiting,"A criação deveria aguardar a alteração do equipamento");}assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM tickets WHERE asset_id=?",Integer.class,a.getId()));}}
 Result upload(Ticket t,User actor,String name,String mime,byte[] bytes)throws Exception{var file=new MockMultipartFile("file",name,mime,bytes);var r=mvc.perform(multipart("/tickets/"+t.getId()+"/attachment").file(file).header("Authorization","Bearer "+tokens.generateToken(actor))).andReturn().getResponse();return new Result(r.getStatus(),json.readTree(r.getContentAsString()));}
 @ParameterizedTest @ValueSource(strings={"png","jpeg"}) void validImagesHaveSafeMimeHeadersAndSurviveStatusChanges(String format)throws Exception{var t=ticket(requester,null);byte[] bytes=format.equals("png")?TestImages.png():TestImages.jpeg();String mime="image/"+format;assertEquals(200,upload(t,requester,"captura."+(format.equals("png")?"png":"jpg"),mime,bytes).status);jdbc.update("UPDATE tickets SET attachment_content_type='text/html' WHERE id=?",t.getId());for(User actor:List.of(admin,tech,requester)){var r=mvc.perform(get("/tickets/"+t.getId()+"/attachment").header("Authorization","Bearer "+tokens.generateToken(actor))).andReturn().getResponse();assertEquals(200,r.getStatus());assertEquals(mime,r.getContentType());assertEquals("nosniff",r.getHeader("X-Content-Type-Options"));assertEquals("default-src 'none'; sandbox",r.getHeader("Content-Security-Policy"));assertArrayEquals(bytes,r.getContentAsByteArray());}assertEquals(200,call("PATCH","/tickets/"+t.getId()+"/technician",Map.of("technicianId",tech.getId(),"expectedVersion",1),admin).status);assertEquals(200,call("PATCH","/tickets/"+t.getId()+"/status",Map.of("status","EM_ATENDIMENTO","expectedVersion",2),tech).status);assertEquals(200,call("PATCH","/tickets/"+t.getId()+"/status",Map.of("status","RESOLVIDO","solution","Solução preservada","expectedVersion",3),tech).status);assertArrayEquals(bytes,tickets.findById(t.getId()).orElseThrow().getAttachmentData());}
 static Stream<Arguments> invalidFiles(){byte[] png=TestImages.png(),jpeg=TestImages.jpeg(),crc=png.clone(),huge=png.clone();crc[29]^=1;java.nio.ByteBuffer.wrap(huge,16,4).putInt(100000);java.util.zip.CRC32 sum=new java.util.zip.CRC32();sum.update(huge,12,17);java.nio.ByteBuffer.wrap(huge,29,4).putInt((int)sum.getValue());return Stream.of(Arguments.of("fake.png","image/png","<script>invalid</script>".getBytes()),Arguments.of("fake.exe","image/png",png),Arguments.of("wrong.jpg","image/jpeg",png),Arguments.of("wrong.png","image/png",jpeg),Arguments.of("truncated.png","image/png",Arrays.copyOf(png,png.length-5)),Arguments.of("truncated.jpg","image/jpeg",Arrays.copyOf(jpeg,jpeg.length-2)),Arguments.of("crc.png","image/png",crc),Arguments.of("large-dimensions.png","image/png",huge),Arguments.of("../image.png","image/png",png),Arguments.of("C:\\image.png","image/png",png),Arguments.of("image\r\nX-Evil.png","image/png",png),Arguments.of("too-large.png","image/png",new byte[2*1024*1024+1]),Arguments.of("header.png","image/png",Arrays.copyOf(png,8)));}
 @ParameterizedTest @MethodSource("invalidFiles") void invalidImagesAreRejectedWithoutPersistenceOrInternalErrors(String name,String mime,byte[] bytes)throws Exception{var t=ticket(requester,null);var r=upload(t,requester,name,mime,bytes);assertEquals(400,r.status);assertFalse(r.body.toString().contains("java."));assertFalse(r.body.has("stackTrace"));assertNull(tickets.findById(t.getId()).orElseThrow().getAttachmentData());}
 @Test void actualStreamSizeIsEnforcedEvenWhenReportedSizeLies()throws Exception{var t=ticket(requester,null);var file=new MockMultipartFile("file","image.png","image/png",new byte[2*1024*1024+1]){public long getSize(){return 1;}};assertEquals(400,mvc.perform(multipart("/tickets/"+t.getId()+"/attachment").file(file).header("Authorization","Bearer "+tokens.generateToken(requester))).andReturn().getResponse().getStatus());}
 @Test void onlyOwningRequesterMayUploadAndOtherRequesterCannotRead()throws Exception{var t=ticket(requester,null);for(User actor:List.of(admin,tech,other))assertEquals(403,upload(t,actor,"valid.png","image/png",TestImages.png()).status);assertEquals(200,upload(t,requester,"valid.png","image/png",TestImages.png()).status);assertEquals(403,mvc.perform(get("/tickets/"+t.getId()+"/attachment").header("Authorization","Bearer "+tokens.generateToken(other))).andReturn().getResponse().getStatus());}
 @Test void concurrentUploadsKeepOneOriginalAndOneRevision()throws Exception{var t=ticket(requester,null);var r=race(()->upload(t,requester,"one.png","image/png",TestImages.png()),()->upload(t,requester,"two.jpg","image/jpeg",TestImages.jpeg()));assertEquals(List.of(200,400),r.stream().map(Result::status).sorted().toList());assertEquals(1,tickets.findById(t.getId()).orElseThrow().getVersion());}
 @Test void legacyUnsafeFilenameNeverEntersDownloadHeaders()throws Exception{var t=ticket(requester,null);t.setAttachmentData(TestImages.png());t.setAttachmentContentType("text/html");t.setAttachmentName("../unsafe\r\nX-Evil: yes.png");t=tickets.saveAndFlush(t);var r=mvc.perform(get("/tickets/"+t.getId()+"/attachment").header("Authorization","Bearer "+tokens.generateToken(requester))).andReturn().getResponse();assertEquals(200,r.getStatus());assertEquals("image/png",r.getContentType());assertEquals("inline; filename=\"anexo-"+t.getId()+".png\"",r.getHeader("Content-Disposition"));assertNull(r.getHeader("X-Evil"));}
 @Test void migrationFromV9PreservesLegacyCodeAndDoesNotInventAudit()throws Exception{String url=newDatabase("assets_migration_");String user=System.getenv("HELPDESK_DISPOSABLE_TEST_PG_USER"),pwd=System.getenv("HELPDESK_DISPOSABLE_TEST_PG_PASSWORD");org.flywaydb.core.Flyway.configure().dataSource(url,user,pwd).target("9").load().migrate();try(var c=connect(url);var st=c.createStatement()){st.execute("INSERT INTO assets(id,code,type,status,description) VALUES(1,' legacy-01 ','Notebook','DISCARDED','Descrição antiga')");String before;try(var r=st.executeQuery("SELECT to_jsonb(a)::text FROM assets a WHERE id=1")){r.next();before=r.getString(1);}var flyway=org.flywaydb.core.Flyway.configure().dataSource(url,user,pwd).load();assertEquals(1,flyway.migrate().migrationsExecuted);assertEquals(0,flyway.migrate().migrationsExecuted);try(var r=st.executeQuery("SELECT (to_jsonb(a)-'version')::text,version FROM assets a WHERE id=1")){r.next();assertEquals(before,r.getString(1));assertEquals(0,r.getLong(2));}try(var r=st.executeQuery("SELECT count(*) FROM asset_audit_logs")){r.next();assertEquals(0,r.getInt(1));}}}
 @Test void migrationStopsOnNormalizedLegacyCollisionWithoutChangingData()throws Exception{String url=newDatabase("assets_collision_");String user=System.getenv("HELPDESK_DISPOSABLE_TEST_PG_USER"),pwd=System.getenv("HELPDESK_DISPOSABLE_TEST_PG_PASSWORD");org.flywaydb.core.Flyway.configure().dataSource(url,user,pwd).target("9").load().migrate();try(var c=connect(url);var st=c.createStatement()){st.execute("INSERT INTO assets(code,type,status) VALUES(' LEGACY ','Notebook','IN_USE'),('legacy','Notebook','IN_USE')");assertThrows(org.flywaydb.core.api.FlywayException.class,()->org.flywaydb.core.Flyway.configure().dataSource(url,user,pwd).load().migrate());try(var r=st.executeQuery("SELECT count(*) FROM assets")){r.next();assertEquals(2,r.getInt(1));}try(var r=st.executeQuery("SELECT count(*) FROM information_schema.columns WHERE table_name='assets' AND column_name='version'")){r.next();assertEquals(0,r.getInt(1));}}}
}